def load(swap=False):
    x=[]; y=[]
    with open('graphene.dat') as f:
        for line in f:
            p=line.strip().split()
            if len(p)<2: continue
            a=float(p[0].replace(',','.')); b=float(p[1].replace(',','.'))
            if swap:
                x.append(b); y.append(a)
            else:
                x.append(a); y.append(b)
    pairs=sorted(zip(x,y))
    return [a for a,b in pairs], [b for a,b in pairs]

def smooth(vals,w):
    out=[]
    for i in range(len(vals)):
        lo=max(0,i-w); hi=min(len(vals),i+w+1)
        out.append(sum(vals[lo:hi])/(hi-lo))
    return out

for swap in [False, True]:
    x,y=load(swap)
    print('\n=== swap=',swap,'=== x range',x[0],x[-1],'n',len(x),'max y',max(y),'at',x[y.index(max(y))])
    ys=smooth(y,5); bg=smooth(y,150)
    cands=[]
    for i in range(1,len(ys)-1):
        if ys[i]>ys[i-1] and ys[i]>=ys[i+1] and x[i]>1000:
            cands.append((ys[i]-bg[i], x[i], y[i], ys[i], bg[i]))
    cands.sort(reverse=True)
    print('top peaks:')
    for c in cands[:15]:
        print(f'x={c[1]:.3f} raw={c[2]:.3f} smooth={c[3]:.3f} bg={c[4]:.3f} prom={c[0]:.3f}')
    laser=19139.544
